# API-equivalent pricing ratios fitted in note 01M2QXT0: input 1, cache write 1.25, cache read 0.1, output 5, at $5.27/M input-equivalent.
RATE = 5.27e-6
def cost(u):
    return RATE * ((u.get("input_tokens") or 0) + 1.25*(u.get("cache_creation_input_tokens") or 0)
                   + 0.1*(u.get("cache_read_input_tokens") or 0) + 5*(u.get("output_tokens") or 0))
ERR = "CouldntReadCurrentDirectory"
for arm in ["claude-sofar", "claude-automemory", "claude-bare"]:
    d = os.path.expanduser(f"~/.bench/claude-config/projects/-Users-Shared-bench-cells-boopada-smoke-r2-claude-diag-{arm}-r1-repo")
    fs = glob.glob(f"{d}/*.jsonl")
    if not fs: print(arm, "no transcript"); continue
    lines = [json.loads(l) for f in fs for l in open(f, errors="replace") if l.strip() and l.startswith("{")]
    # map tool_use_id -> assistant message index that issued it
    issuer, order, msgs = {}, [], []
    for e in lines:
        m = e.get("message") or {}
        if e.get("type") == "assistant" and isinstance(m.get("content"), list):
            idx = len(msgs); msgs.append(e)
            for b in m["content"]:
                if b.get("type") == "tool_use": issuer[b.get("id")] = idx
        elif e.get("type") == "user" and isinstance(m.get("content"), list):
            for b in m["content"]:
                if b.get("type") == "tool_result" and ERR in json.dumps(b.get("content"))[:8000]:
                    order.append(b.get("tool_use_id"))
    flagged = set()
    for tid in order:
        i = issuer.get(tid)
        if i is None: continue
        flagged.add(i)          # the turn that issued the failing command
        if i+1 < len(msgs): flagged.add(i+1)   # and the next turn, the recovery
    seen, total_cost, flag_cost, total_out, flag_out = set(), 0.0, 0.0, 0, 0
    for i, e in enumerate(msgs):
        mid = (e.get("message") or {}).get("id")
        if mid in seen: continue
        seen.add(mid)
        u = (e.get("message") or {}).get("usage") or {}
        c = cost(u); total_cost += c; total_out += u.get("output_tokens") or 0
        if i in flagged: flag_cost += c; flag_out += u.get("output_tokens") or 0
    print(f"{arm:18} errors={len(order):2} flagged_turns={len(flagged):2} of {len(seen):3} | "
          f"attributable ${flag_cost:.2f} of ${total_cost:.2f} = {100*flag_cost/max(total_cost,1e-9):.1f}% | out_tokens {flag_out}/{total_out}")
