  /** sofar's store is per branch: worktree sessions need their branch bound (--worktree-binding). */
  usesSofar: boolean
}

/** The native-synced Claude arm: auto memory in one carried directory per cell (the D1 stand-in, R3 §4.1). */
export function nativeMemoryDir(cellDir: string): string {
  return join(cellDir, "native-memory", "claude")
}

