  id: "claude-native-synced",
  agent: "claude-code",
  store: () => "Claude Code's built-in auto memory",
  async setup({ repo, cellDir }) {
    mkdirSync(nativeMemoryDir(cellDir), { recursive: true })
    claudeLocalSettings(repo, { autoMemoryEnabled: true, autoMemoryDirectory: nativeMemoryDir(cellDir) })
  },
  mcpConfig: EMPTY_MCP,
}

