  sofar: {
    id: "sofar",
    perAgent: { "claude-code": ARMS["claude-sofar"] as Arm, codex: ARMS["codex-sofar"] as Arm, cursor: ARMS["cursor-sofar"] as Arm },
    async setup({ repo }) {
      await sofarInit(repo, "claude-code,codex,cursor")
