    async setup(ctx) {
      await claudeNativeSynced.setup(ctx)
    },
    stores: ({ repo, cellDir }) => [
      [nativeMemoryDir(cellDir), "claude-native-memory"],
      [join(cellDir, "codex-home", "memories"), "codex-memories"],
      [join(repo, ".cursor", "rules"), "cursor-rules"],
      [join(repo, "AGENTS.md"), "cursor-agents-md"],
    ],
    usesSofar: false,
  },
}

/** The Arm a chain-arm session launches with: its agent's arm, snapshotting the whole condition's stores. */
export function sessionArm(chainArm: ChainArm, agent: AgentId): Arm {
  const base = chainArm.perAgent[agent]
  return { ...base, id: base.id, nativeStores: (ctx) => chainArm.stores(ctx) }
}
