 * The sofar arm's worktree binding. On 0.34.0-rc.2 a new branch is bound to no initiative, and sofar
 * falls back to the most recently active one, with a warning: the cell's record in a fresh repo, but
 * `quick` in a cell whose quick lane was last active (round 2's smoke cell). What a worktree session
 * sees is therefore state-dependent unless the branch is bound. `switch` binds each worktree branch
 * with `sofar switch <slug>`, the documented step a teammate takes; `none` leaves them unbound. It is
 * an arm-fairness choice with no default: the run owner rules it.
 */
export type WorktreeBinding = "switch" | "none"

/**
 * `switch`, done so the harness adds no merge conflict of its own. `sofar switch` writes the branch
 * into the tracked .sofar/bindings.json, so binding each worktree on its own branch gives every
 * branch a different bindings file and a guaranteed conflict at the merge, in the sofar arm only
 * (the first fake-chain run showed it). Instead, before the worktrees exist, every branch is bound in
 * a scratch checkout of main by sofar itself, the result is committed once on main, and the worktrees
 * branch from that commit, so they all carry the same bindings. Returns the slug, or null when there is
 * nothing to bind yet (no initiative on main) or binding is `none`.
 */
export async function prebindWorktrees(repo: string, branches: string[], sofarBin: string, binding: WorktreeBinding, env: Record<string, string>, label: string): Promise<string | null> {
  if (binding === "none" || !branches.length) return null
  const file = join(repo, ".sofar", "bindings.json")
  const slug = existsSync(file) ? (JSON.parse(readFileSync(file, "utf8")) as Record<string, string>).main : undefined
  if (!slug) return null
  const scratch = `${repo}-bind-${process.pid}`
  await gitOk(repo, "worktree", "add", "-q", "--detach", scratch, "HEAD")
  try {
    for (const b of branches) {
      await gitOk(scratch, "checkout", "-q", "-B", `bench-bind-${b}`)
      // sofar binds the CURRENT branch, so the scratch checkout takes each worktree's name in turn.
      await gitOk(scratch, "branch", "-q", "-M", b)
      const r = await run([sofarBin, "switch", slug], { cwd: scratch, env, timeoutMs: 120_000 })
      if (r.code !== 0) throw new Error(`sofar switch ${slug} on ${b} failed: ${r.stderr || r.stdout}`)
      await gitOk(scratch, "checkout", "-q", "--detach")
      await gitOk(scratch, "branch", "-q", "-D", b)
    }
    cpSync(join(scratch, ".sofar", "bindings.json"), file)
  } finally {
    await gitOk(repo, "worktree", "remove", "--force", scratch)
  }
  await gitOk(repo, "add", ".sofar/bindings.json")
  await gitOk(repo, "commit", "-q", "--no-verify", "-m", `bench: bind ${branches.join(", ")} to ${slug} before ${label}`)
  return slug
}
'''
